CREATE OR REPLACE FUNCTION public.admin_decide_deferred_signature_approval(p_request_id uuid, p_decision text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r public.assist_visit_signature_requests%ROWTYPE;
  v_profile_id uuid;
  v_status text;
BEGIN
  IF NOT public.has_permission('assist.execution.manage') THEN
    RAISE EXCEPTION 'Keine Berechtigung';
  END IF;
  IF p_decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'Ungültige Entscheidung';
  END IF;
  IF p_decision = 'rejected' AND length(trim(coalesce(p_reason, ''))) = 0 THEN
    RAISE EXCEPTION 'Bei Ablehnung ist eine Begründung erforderlich';
  END IF;

  SELECT * INTO r
    FROM public.assist_visit_signature_requests
   WHERE id = p_request_id AND tenant_id = public.current_tenant_id()
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Freigabeanfrage nicht gefunden'; END IF;
  IF r.status IN ('approved', 'rejected') THEN
    RETURN jsonb_build_object('request_id', r.id, 'visit_id', r.visit_id, 'status', r.status);
  END IF;
  IF r.status <> 'pending_admin_approval' THEN RAISE EXCEPTION 'Anfrage ist nicht entscheidbar'; END IF;

  IF p_decision = 'approved' AND NOT EXISTS (
    SELECT 1 FROM public.assist_visit_proofs p
     WHERE p.tenant_id = r.tenant_id AND p.visit_id = r.visit_id
       AND p.portal_visible = true
       AND p.portal_release_status = 'pending_client_signature'
  ) THEN
    RAISE EXCEPTION 'Portal-Veröffentlichung wurde noch nicht bestätigt';
  END IF;

  v_profile_id := public.resolve_current_profile_id();
  v_status := p_decision;
  UPDATE public.assist_visit_signature_requests
     SET status = v_status,
         decision_by_profile_id = v_profile_id,
         decision_at = now(),
         decision_reason = nullif(trim(coalesce(p_reason, '')), '')
   WHERE id = r.id;

  IF p_decision = 'approved' THEN
    UPDATE public.assist_visits
       SET execution_status = 'completed', canonical_status = 'completed',
           proof_status = 'pending', billing_status = 'blocked',
           finished_at = coalesce(finished_at, actual_end_at),
           updated_by = v_profile_id, updated_at = now()
     WHERE id = r.visit_id AND tenant_id = r.tenant_id;
    UPDATE public.assignments
       SET status = 'completed', updated_at = now()
     WHERE id = coalesce(
       (SELECT legacy_assignment_id FROM public.assist_visits
         WHERE id = r.visit_id AND tenant_id = r.tenant_id),
       r.visit_id
     ) AND tenant_id = r.tenant_id;
    UPDATE public.assist_visit_execution_state
       SET current_step = 'completed', assignment_status = 'abgeschlossen',
           documentation_complete = true, signature_complete = false,
           proof_generated = false, finalized_at = now(), updated_at = now(),
           metadata = metadata || jsonb_build_object('signature_deferred_to_client_portal', true)
     WHERE visit_id = r.visit_id AND tenant_id = r.tenant_id;
  END IF;

  INSERT INTO public.assist_visit_admin_audit(tenant_id, visit_id, action, previous_value, new_value, reason)
  VALUES (
    r.tenant_id, r.visit_id,
    CASE WHEN p_decision = 'approved'
      THEN 'deferred_signature_approval_approved'
      ELSE 'deferred_signature_approval_rejected' END,
    jsonb_build_object('status', r.status),
    jsonb_build_object('status', v_status, 'request_id', r.id),
    coalesce(nullif(trim(coalesce(p_reason, '')), ''), 'Durch Verwaltung genehmigt')
  );
  RETURN jsonb_build_object('request_id', r.id, 'visit_id', r.visit_id, 'status', v_status);
END $function$

CREATE OR REPLACE FUNCTION public.admin_release_deferred_signature(p_tenant_id uuid, p_proof_id uuid, p_client_id uuid, p_title text, p_payload_snapshot jsonb, p_payload_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid;
  v_proof public.assist_visit_proofs%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Anmeldung ist erforderlich';
  END IF;
  IF p_tenant_id IS NULL OR p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'Mandant stimmt nicht überein';
  END IF;
  IF NOT coalesce(public.is_tenant_admin() OR public.has_permission('assist.execution.manage'), FALSE) THEN
    RAISE EXCEPTION 'Keine Berechtigung';
  END IF;
  v_actor := public.resolve_current_profile_id();
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Angemeldetes Verwaltungsprofil konnte nicht zugeordnet werden';
  END IF;
  IF p_proof_id IS NULL OR p_client_id IS NULL
     OR p_payload_snapshot IS NULL OR jsonb_typeof(p_payload_snapshot) <> 'object'
     OR nullif(trim(coalesce(p_payload_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION 'Angaben zur Signaturanforderung sind unvollständig';
  END IF;

  SELECT * INTO v_proof
  FROM public.assist_visit_proofs
  WHERE tenant_id = p_tenant_id AND id = p_proof_id
  FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Nachweis nicht gefunden'; END IF;

  PERFORM 1 FROM public.assist_visits
  WHERE tenant_id = p_tenant_id AND id = v_proof.visit_id AND client_id = p_client_id
  FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Signaturanforderung ist nicht eindeutig dem Klienten zugeordnet';
  END IF;
  IF v_proof.signature_id IS NOT NULL OR v_proof.status IN ('approved', 'exported', 'archived') THEN
    RAISE EXCEPTION 'Der Nachweis ist bereits unterschrieben oder freigegeben';
  END IF;

  IF v_proof.portal_visible AND v_proof.portal_release_status = 'pending_client_signature' THEN
    IF EXISTS (
      SELECT 1 FROM public.client_documents
      WHERE id = p_proof_id AND tenant_id = p_tenant_id AND client_id = p_client_id
        AND source = 'assist_visit_proof' AND portal_visible
        AND signature_required AND signed_at IS NULL AND status = 'aktiv'
    ) THEN
      RETURN p_proof_id;
    END IF;
  ELSE
    UPDATE public.assist_visit_proofs
    SET payload_snapshot = p_payload_snapshot,
        payload_hash = trim(p_payload_hash),
        portal_visible = TRUE,
        portal_release_status = 'pending_client_signature',
        released_to_portal_at = now(),
        updated_by = v_actor,
        updated_at = now()
    WHERE id = p_proof_id AND tenant_id = p_tenant_id;
  END IF;

  INSERT INTO public.client_documents (
    id, tenant_id, client_id, title, file_name, mime_type, category,
    storage_path, portal_visible, status, sensitivity, source, uploaded_by,
    signed_at, signature_required, updated_at
  ) VALUES (
    p_proof_id, p_tenant_id, p_client_id,
    coalesce(nullif(trim(p_title), ''), 'Leistungsnachweis') || ' — Unterschrift ausstehend',
    'unterschrift-' || p_proof_id::text || '.pending', 'application/pdf',
    'leistungsnachweis', NULL, TRUE, 'aktiv', 'care', 'assist_visit_proof',
    v_actor, NULL, TRUE, now()
  )
  ON CONFLICT (id) DO UPDATE SET
    portal_visible = TRUE,
    signature_required = TRUE,
    status = 'aktiv',
    updated_at = now()
  WHERE client_documents.tenant_id = EXCLUDED.tenant_id
    AND client_documents.client_id = EXCLUDED.client_id
    AND client_documents.source = 'assist_visit_proof'
    AND client_documents.signed_at IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Portal-Dokument ist bereits unterschrieben oder nicht eindeutig zugeordnet';
  END IF;
  RETURN p_proof_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_request_assist_visit_signature(p_visit_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v public.assist_visits%ROWTYPE; v_request_id uuid;
BEGIN
  IF NOT public.has_permission('assist.execution.manage') THEN RAISE EXCEPTION 'Keine Berechtigung'; END IF;
  IF length(trim(coalesce(p_reason,''))) = 0 THEN RAISE EXCEPTION 'Begr├╝ndung ist erforderlich'; END IF;
  SELECT * INTO v FROM public.assist_visits WHERE id=p_visit_id AND tenant_id=public.current_tenant_id() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Einsatz nicht gefunden'; END IF;
  SELECT id INTO v_request_id FROM public.assist_visit_signature_requests
   WHERE tenant_id=v.tenant_id AND visit_id=v.id AND status='open';
  IF v_request_id IS NULL THEN
    INSERT INTO public.assist_visit_signature_requests(
      tenant_id,visit_id,client_id,service_date,service_name,planned_start_at,planned_end_at,
      actual_start_at,actual_end_at,proof_preview)
    VALUES(v.tenant_id,v.id,v.client_id,v.assignment_date,coalesce(nullif(v.service_name,''),v.title),
      v.planned_start_at,v.planned_end_at,v.actual_start_at,v.actual_end_at,
      jsonb_build_object('visit_id',v.id,'service_date',v.assignment_date,'service',coalesce(nullif(v.service_name,''),v.title),
        'planned_start_at',v.planned_start_at,'planned_end_at',v.planned_end_at,
        'actual_start_at',v.actual_start_at,'actual_end_at',v.actual_end_at)) RETURNING id INTO v_request_id;
    UPDATE public.assist_visits SET proof_status='pending', updated_by=auth.uid(), updated_at=now() WHERE id=v.id;
    INSERT INTO public.assist_visit_admin_audit(tenant_id,visit_id,action,new_value,reason)
    VALUES(v.tenant_id,v.id,'signature_requested',jsonb_build_object('request_id',v_request_id),p_reason);
  END IF;
  RETURN v_request_id;
END $function$

CREATE OR REPLACE FUNCTION public.admin_upsert_deferred_signature_client_document(p_tenant_id uuid, p_proof_id uuid, p_client_id uuid, p_title text, p_actor_profile_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor UUID := public.resolve_current_profile_id();
  v_title TEXT;
BEGIN
  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'Mandant stimmt nicht überein';
  END IF;
  IF NOT (public.is_tenant_admin() OR public.has_permission('assist.execution.manage')) THEN
    RAISE EXCEPTION 'Keine Berechtigung';
  END IF;
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Angemeldetes Verwaltungsprofil konnte nicht zugeordnet werden';
  END IF;
  IF p_actor_profile_id IS NOT NULL AND p_actor_profile_id IS DISTINCT FROM v_actor THEN
    RAISE EXCEPTION 'Verwaltungsprofil stimmt nicht mit der Sitzung überein';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.assist_visit_proofs p
    JOIN public.assist_visits v
      ON v.tenant_id = p.tenant_id AND v.id = p.visit_id
    WHERE p.tenant_id = p_tenant_id
      AND p.id = p_proof_id
      AND v.client_id = p_client_id
      AND p.portal_visible = TRUE
      AND p.portal_release_status = 'pending_client_signature'
  ) THEN
    RAISE EXCEPTION 'Signaturanforderung ist nicht eindeutig dem Klienten zugeordnet';
  END IF;

  v_title := coalesce(nullif(trim(p_title), ''), 'Leistungsnachweis')
    || ' — Unterschrift ausstehend';

  INSERT INTO public.client_documents (
    id, tenant_id, client_id, title, file_name, mime_type, category,
    storage_path, portal_visible, status, sensitivity, source, uploaded_by,
    signed_at, signature_required, updated_at
  ) VALUES (
    p_proof_id, p_tenant_id, p_client_id, v_title,
    'unterschrift-' || p_proof_id::text || '.pending', 'application/pdf',
    'leistungsnachweis', NULL, TRUE, 'aktiv', 'care', 'assist_visit_proof',
    v_actor, NULL, TRUE, now()
  )
  ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    file_name = EXCLUDED.file_name,
    storage_path = NULL,
    portal_visible = TRUE,
    status = 'aktiv',
    category = 'leistungsnachweis',
    signed_at = NULL,
    signature_required = TRUE,
    source = 'assist_visit_proof',
    uploaded_by = v_actor,
    updated_at = now();

  RETURN p_proof_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.client_portal_sign_document_request(p_tenant_id uuid, p_request_id uuid, p_signer_role text, p_signer_name text, p_signature_data_url text, p_expected_updated_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_request public.cs_document_requests%ROWTYPE;
  v_signed_at timestamptz := now();
  v_html text;
  v_image text;
  v_anchor text;
  v_pattern text;
  v_all_done boolean;
BEGIN
  IF auth.uid() IS NULL OR p_tenant_id IS DISTINCT FROM public.current_tenant_id()
     OR NOT coalesce(public.is_client_portal_rls_context(p_tenant_id), false)
     OR public.current_client_id() IS NULL OR p_signer_role NOT IN ('client', 'representative')
     OR p_signer_role IS NULL THEN RAISE EXCEPTION 'Keine Berechtigung für diese Unterschrift'; END IF;
  SELECT * INTO v_request FROM public.cs_document_requests
    WHERE id = p_request_id AND owner_tenant_id = p_tenant_id
      AND client_id = public.current_client_id() AND portal_visible
      AND recipient_scope IN ('client', 'both') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dokument nicht für Sie freigegeben'; END IF;
  IF EXISTS (SELECT 1 FROM public.cs_document_request_signatures
      WHERE request_id = p_request_id AND signer_role = p_signer_role AND status = 'signed')
     AND NOT EXISTS (SELECT 1 FROM public.cs_document_request_signatures
      WHERE request_id = p_request_id AND signer_role = p_signer_role AND status = 'pending') THEN
    RETURN p_request_id;
  END IF;
  IF v_request.status NOT IN ('sent', 'opened', 'partially_signed')
     OR v_request.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'Dokument wurde geändert. Bitte neu laden und prüfen';
  END IF;
  IF nullif(trim(p_signer_name), '') IS NULL OR length(p_signer_name) > 300
     OR p_signature_data_url IS NULL OR length(p_signature_data_url) > 3000000
     OR p_signature_data_url !~ '^data:image/png;base64,[A-Za-z0-9+/]+={0,2}$'
     OR nullif(trim(v_request.rendered_html), '') IS NULL THEN
    RAISE EXCEPTION 'Signatur oder Dokumentvorschau ist unvollständig';
  END IF;
  UPDATE public.cs_document_request_signatures SET status = 'signed', signer_name = trim(p_signer_name),
    signature_data_url = p_signature_data_url, signed_at = v_signed_at, updated_at = v_signed_at
    WHERE request_id = p_request_id AND signer_role = p_signer_role AND status = 'pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Keine offene Unterschrift für diese Rolle'; END IF;
  -- Derive the HTML from the locked original. The portal cannot replace document text.
  v_anchor := p_signer_role || '_signature';
  v_image := '<img src="' || p_signature_data_url || '" alt="Unterschrift" style="max-height:80px;max-width:240px;" /><br/><small>'
    || replace(replace(replace(trim(p_signer_name), '&', '&amp;'), '<', '&lt;'), '>', '&gt;')
    || ' · ' || to_char(v_signed_at AT TIME ZONE 'Europe/Berlin', 'DD.MM.YYYY HH24:MI:SS') || '</small>';
  v_pattern := '(<span[^>]*data-signature-anchor="' || v_anchor || '"[^>]*>)(\[SIGNATURE:[^]]+\])(</span>)';
  IF v_request.rendered_html ~* v_pattern THEN
    v_html := regexp_replace(v_request.rendered_html, v_pattern, '\1' || replace(v_image, E'\\', E'\\\\') || '\3', 'i');
  ELSE
    v_html := v_request.rendered_html || '<p data-signature-anchor="' || v_anchor || '">' || v_image || '</p>';
  END IF;
  SELECT NOT EXISTS (SELECT 1 FROM public.cs_document_request_signatures
    WHERE request_id = p_request_id AND status NOT IN ('signed', 'not_required')) INTO v_all_done;
  UPDATE public.cs_document_requests SET status = CASE WHEN v_all_done THEN 'completed' ELSE 'partially_signed' END,
    rendered_html = v_html, completed_at = CASE WHEN v_all_done THEN v_signed_at ELSE NULL END, updated_at = v_signed_at
    WHERE id = p_request_id AND owner_tenant_id = p_tenant_id;
  INSERT INTO public.audit_logs (tenant_id, action, record_id, table_name, title, new_data)
    VALUES (p_tenant_id, 'signature', p_request_id, 'cs_document_requests', 'Dokument im Klientenportal unterzeichnet',
      jsonb_build_object('event', 'document_request_signed', 'signer_role', p_signer_role, 'signed_at', v_signed_at, 'actor_user_id', auth.uid()));
  RETURN p_request_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.employee_portal_release_deferred_signature(p_tenant_id uuid, p_proof_id uuid, p_client_id uuid, p_title text, p_payload_snapshot jsonb, p_payload_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_visit_id uuid;
  v_employee_id uuid;
  v_actor_profile_id uuid;
  v_signature_id uuid;
  v_doc_title text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: authentication required';
  END IF;
  IF p_tenant_id IS NULL OR p_proof_id IS NULL OR p_client_id IS NULL
     OR p_payload_snapshot IS NULL OR nullif(trim(coalesce(p_payload_hash, '')), '') IS NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: missing required parameters';
  END IF;
  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: tenant mismatch';
  END IF;
  IF NOT public.is_employee_portal_rls_context(p_tenant_id) THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: employee portal role required';
  END IF;

  v_employee_id := public.resolve_current_employee_id();
  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: employee not resolved';
  END IF;

  v_actor_profile_id := public.resolve_current_profile_id();
  IF v_actor_profile_id IS NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: profile not resolved';
  END IF;

  SELECT avp.visit_id, avp.signature_id
    INTO v_visit_id, v_signature_id
  FROM public.assist_visit_proofs avp
  WHERE avp.tenant_id = p_tenant_id
    AND avp.id = p_proof_id
  FOR UPDATE;

  IF v_visit_id IS NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: proof not found';
  END IF;
  IF v_signature_id IS NOT NULL THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: proof already signed';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.assist_visits v
    WHERE v.tenant_id = p_tenant_id
      AND v.id = v_visit_id
      AND v.client_id = p_client_id
      AND v.employee_id = v_employee_id
  ) AND NOT EXISTS (
    SELECT 1
    FROM public.assignments a
    JOIN public.assist_visits v
      ON v.tenant_id = a.tenant_id
     AND (v.legacy_assignment_id = a.id OR v.id = a.id)
    WHERE a.tenant_id = p_tenant_id
      AND v.id = v_visit_id
      AND a.client_id = p_client_id
      AND a.employee_id = v_employee_id
  ) THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: visit not assigned to employee';
  END IF;

  UPDATE public.assist_visit_proofs
  SET payload_snapshot = p_payload_snapshot,
      payload_hash = trim(p_payload_hash),
      signature_id = NULL,
      portal_visible = TRUE,
      portal_release_status = 'pending_client_signature',
      released_to_portal_at = now(),
      updated_by = v_actor_profile_id,
      updated_at = now()
  WHERE tenant_id = p_tenant_id
    AND id = p_proof_id
    AND signature_id IS NULL;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: proof update failed';
  END IF;

  v_doc_title := coalesce(nullif(trim(p_title), ''), 'Leistungsnachweis') ||
    ' ÔÇö Unterschrift ausstehend';

  INSERT INTO public.client_documents (
    id, tenant_id, client_id, title, file_name, mime_type, category,
    storage_path, portal_visible, status, sensitivity, source, uploaded_by,
    signed_at, signature_required, updated_at
  ) VALUES (
    p_proof_id, p_tenant_id, p_client_id, v_doc_title,
    'unterschrift-' || p_proof_id::text || '.pending', 'application/pdf',
    'leistungsnachweis', NULL, TRUE, 'aktiv', 'care', 'assist_visit_proof',
    v_actor_profile_id, NULL, TRUE, now()
  )
  ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    file_name = EXCLUDED.file_name,
    storage_path = NULL,
    portal_visible = TRUE,
    status = 'aktiv',
    category = 'leistungsnachweis',
    signed_at = NULL,
    signature_required = TRUE,
    source = 'assist_visit_proof',
    updated_at = now()
  WHERE client_documents.tenant_id = EXCLUDED.tenant_id
    AND client_documents.client_id = EXCLUDED.client_id
    AND client_documents.source = 'assist_visit_proof';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'employee_portal_release_deferred_signature: document id conflict';
  END IF;

  RETURN p_proof_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.employee_portal_upsert_deferred_signature_client_document(p_tenant_id uuid, p_proof_id uuid, p_client_id uuid, p_title text, p_actor_profile_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_visit_id uuid;
  v_employee_id uuid;
  v_doc_title text;
BEGIN
  IF p_tenant_id IS NULL OR p_proof_id IS NULL OR p_client_id IS NULL THEN
    RAISE EXCEPTION 'employee_portal_upsert_deferred_signature_client_document: missing required parameters';
  END IF;

  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'employee_portal_upsert_deferred_signature_client_document: tenant mismatch';
  END IF;

  IF NOT public.is_employee_portal_rls_context(p_tenant_id)
     AND NOT public.is_tenant_member(p_tenant_id) THEN
    RAISE EXCEPTION 'employee_portal_upsert_deferred_signature_client_document: insufficient permissions';
  END IF;

  v_employee_id := public.resolve_current_employee_id();
  IF v_employee_id IS NULL THEN
    RAISE EXCEPTION 'employee_portal_upsert_deferred_signature_client_document: employee not resolved';
  END IF;

  SELECT avp.visit_id
  INTO v_visit_id
  FROM public.assist_visit_proofs avp
  WHERE avp.tenant_id = p_tenant_id
    AND avp.id = p_proof_id
    AND avp.portal_visible = TRUE
    AND avp.portal_release_status = 'pending_client_signature';

  IF v_visit_id IS NULL THEN
    RAISE EXCEPTION 'employee_portal_upsert_deferred_signature_client_document: proof not pending client signature';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM public.assist_visits v
    WHERE v.tenant_id = p_tenant_id
      AND v.id = v_visit_id
      AND v.client_id = p_client_id
      AND v.employee_id = v_employee_id
  ) AND NOT EXISTS (
    SELECT 1
    FROM public.assignments a
    JOIN public.assist_visits v
      ON v.tenant_id = a.tenant_id
     AND (v.legacy_assignment_id = a.id OR v.id = a.id)
    WHERE a.tenant_id = p_tenant_id
      AND v.id = v_visit_id
      AND a.client_id = p_client_id
      AND a.employee_id = v_employee_id
  ) THEN
    RAISE EXCEPTION 'employee_portal_upsert_deferred_signature_client_document: visit not assigned to employee';
  END IF;

  v_doc_title := COALESCE(NULLIF(trim(p_title), ''), 'Leistungsnachweis') || ' — Unterschrift ausstehend';

  INSERT INTO public.client_documents (
    id, tenant_id, client_id, title, file_name, mime_type, category, storage_path,
    portal_visible, status, sensitivity, source, uploaded_by, signed_at, signature_required, updated_at
  )
  VALUES (
    p_proof_id, p_tenant_id, p_client_id, v_doc_title,
    'unterschrift-' || p_proof_id::text || '.pending', 'application/pdf', 'leistungsnachweis', NULL,
    TRUE, 'aktiv', 'care', 'assist_visit_proof', p_actor_profile_id, NULL, TRUE, now()
  )
  ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title,
    file_name = EXCLUDED.file_name,
    storage_path = EXCLUDED.storage_path,
    portal_visible = EXCLUDED.portal_visible,
    status = EXCLUDED.status,
    category = EXCLUDED.category,
    signed_at = NULL,
    signature_required = TRUE,
    source = EXCLUDED.source,
    updated_at = now();

  RETURN p_proof_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.employee_request_deferred_signature_admin_approval(p_tenant_id uuid, p_visit_id uuid, p_employee_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v public.assist_visits%ROWTYPE;
  v_current_employee uuid;
  v_request_id uuid;
  v_client_name text;
  v_employee_name text;
  v_documentation text;
BEGIN
  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'Mandantenzugriff verweigert';
  END IF;

  v_current_employee := public.resolve_current_employee_id();
  IF v_current_employee IS NULL OR v_current_employee IS DISTINCT FROM p_employee_id THEN
    RAISE EXCEPTION 'Mitarbeitenden-Zuordnung ungültig';
  END IF;
  IF length(trim(coalesce(p_reason, ''))) < 10 THEN
    RAISE EXCEPTION 'Bitte begründen Sie die Weiterleitung mit mindestens 10 Zeichen';
  END IF;

  SELECT * INTO v
    FROM public.assist_visits
   WHERE id = p_visit_id
     AND tenant_id = p_tenant_id
     AND employee_id = p_employee_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Einsatz nicht gefunden'; END IF;
  IF v.actual_end_at IS NULL THEN RAISE EXCEPTION 'Der Einsatz ist noch nicht beendet'; END IF;
  IF coalesce(v.documentation_status, '') <> 'complete' THEN
    RAISE EXCEPTION 'Dokumentation ist noch nicht vollständig';
  END IF;

  SELECT id INTO v_request_id
    FROM public.assist_visit_signature_requests
   WHERE tenant_id = p_tenant_id
     AND visit_id = p_visit_id
     AND status = 'pending_admin_approval';
  IF v_request_id IS NOT NULL THEN RETURN v_request_id; END IF;

  SELECT trim(concat_ws(' ', first_name, last_name)) INTO v_client_name
    FROM public.clients WHERE id = v.client_id AND tenant_id = p_tenant_id;
  SELECT trim(concat_ws(' ', first_name, last_name)) INTO v_employee_name
    FROM public.employees WHERE id = p_employee_id AND tenant_id = p_tenant_id;
  SELECT coalesce(nullif(trim(short_description), ''), nullif(trim(special_notes), ''))
    INTO v_documentation
    FROM public.assist_visit_documentation
   WHERE tenant_id = p_tenant_id AND visit_id = p_visit_id;

  INSERT INTO public.assist_visit_signature_requests(
    tenant_id, visit_id, client_id, employee_id, request_reason, status, service_date, service_name,
    planned_start_at, planned_end_at, actual_start_at, actual_end_at, proof_preview
  ) VALUES (
    p_tenant_id, p_visit_id, v.client_id, p_employee_id, trim(p_reason), 'pending_admin_approval',
    v.assignment_date, coalesce(nullif(v.service_name, ''), v.title),
    v.planned_start_at, v.planned_end_at, v.actual_start_at, v.actual_end_at,
    jsonb_build_object(
      'visit_id', v.id,
      'service_date', v.assignment_date,
      'service', coalesce(nullif(v.service_name, ''), v.title),
      'client_name', coalesce(nullif(v_client_name, ''), 'Klient:in'),
      'employee_name', coalesce(nullif(v_employee_name, ''), 'Mitarbeiter:in'),
      'request_reason', trim(p_reason),
      'planned_start_at', v.planned_start_at,
      'planned_end_at', v.planned_end_at,
      'actual_start_at', v.actual_start_at,
      'actual_end_at', v.actual_end_at,
      'documentation', coalesce(v_documentation, '')
    )
  ) RETURNING id INTO v_request_id;

  INSERT INTO public.assist_visit_admin_audit(tenant_id, visit_id, action, new_value, reason)
  VALUES (
    p_tenant_id, p_visit_id, 'deferred_signature_approval_requested',
    jsonb_build_object('request_id', v_request_id, 'employee_id', p_employee_id),
    'Mitarbeitende Person beantragt Portal-Unterschrift'
  );
  RETURN v_request_id;
END $function$
